class Game:
    def __init__(self):
        pygame.init()
        self.screen_width = 800
        self.screen_height = 600
        self.screen = pygame.display.set_mode((self.screen_width, self.screen_height))
        self.clock = pygame.time.Clock()
        self.font = pygame.font.Font(None, 36)
        self.main_menu = Main_Menu(self.screen)
        self.game_loop = None
        self.score = Score()
        self.running = False

    def run(self):
        running = True
        while running:
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    running = False
                elif event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_SPACE:
                        if not self.running:
                            self.main_menu.handle_input(event)
                            if self.main_menu.game_started:
                                self.score.reset()
                                self.game_loop = Game_Loop(self.screen, self.score)
                                self.running = True
                        else:
                            self.game_loop.handle_input(event)
                            if self.game_loop.game_over:
                                self.running = False

